// githubNote is test_phase3.py's _github_note: a current-format GitHub
// note (Phase-1 stamps, no legacy placeholder sections).
func githubNote(url, categoryKey string, tags ...string) string {
	tagLine := "tags: [" + strings.Join(tags, ", ") + "]"
	if len(tags) == 0 {
		tagLine = "tags: []"
	}
	return "---\n" +
		"source: " + url + "\n" +
		"aliases: []\n" +
		tagLine + "\n" +
		"category: \"" + categoryKey + "\"\n" +
		"stars: 10\n" +
		"managed_by: \"GitCurator\"\n" +
		"---\n" +
		"# repo\n\nSummary text for " + url + ".\n"
}

// websiteNote is test_phase3.py's _website_note.
func websiteNote(url, category, subcategory, name string) string {
	sub := "\"\""
	if subcategory != "" {
		sub = "\"" + subcategory + "\""
	}
	return "---\n" +
		"source: " + url + "\n" +
		"aliases: []\n" +
		"tags: []\n" +
		"category: \"" + category + "\"\n" +
		"subcategory: " + sub + "\n" +
		"fetch_status: \"ok\"\n" +
		"managed_by: \"GitCurator\"\n" +
		"---\n" +
		"# " + name + "\n\n> **TL;DR:** a site\n"
}

