// ---------------------------------------------------------------------------
// 3. The generated pure corpus (fingerprint + replacement semantics +
//    the folder_category matrix — from the unmodified reference).
// ---------------------------------------------------------------------------

type fpCase struct {
	Name     string `json:"name"`
	Kind     string `json:"kind"`
	Input    any    `json:"input"`
	Stripped string `json:"stripped"`
	Sha256   string `json:"sha256"`
}

type pureGolden struct {
	Schema           int      `json:"schema"`
	FingerprintCases []fpCase `json:"fingerprint_cases"`
	FolderCategory   [][]any  `json:"folder_category"`
}

func TestPureGolden(t *testing.T) {
	var g pureGolden
	decodeGolden(t, "notestate_pure.golden.json", &g)

	for _, c := range g.FingerprintCases {
		var text string
		switch c.Kind {
		case "str":
			s, ok := c.Input.(string)
			if !ok {
				t.Fatalf("%s: bad str input %#v", c.Name, c.Input)
			}
			text = s
		case "bytes":
			raw, ok := c.Input.([]any)
			if !ok {
				t.Fatalf("%s: bad bytes input %#v", c.Name, c.Input)
			}
			buf := make([]byte, 0, len(raw))
			for _, e := range raw {
				n, ok := e.(json.Number)
				if !ok {
					t.Fatalf("%s: bad byte %#v", c.Name, e)
				}
				v, err := n.Int64()
				if err != nil {
					t.Fatalf("%s: byte %v: %v", c.Name, n, err)
				}
				buf = append(buf, byte(v))
			}
			// model the reference's OWN file read exactly (the golden's
			// bytes cases do the same): text mode's universal-newlines
			// translation after the replace decode — the crlf_file_read
			// case pins it (SESSION-008 fidelity fix)
			text = helpers.PyNewlines(decodeUTF8Replace(buf))
		default:
			t.Fatalf("unknown kind %q", c.Kind)
		}
		if got := stripRecallBlock(text); got != c.Stripped {
			t.Errorf("%s: stripped = %q; want %q (the recall-strip + rstrip law)",
				c.Name, got, c.Stripped)
		}
		if got := ComputeFingerprint(text); got != c.Sha256 {
			t.Errorf("%s: sha256 = %s; want %s (Python's compute_fingerprint, replacement semantics included)",
				c.Name, got, c.Sha256)
		}
	}

	for _, row := range g.FolderCategory {
		if len(row) != 3 {
			t.Fatalf("folder_category row = %v; want [folder, cat, sub]", row)
		}
		folder, _ := row[0].(string)
		cat, sub := FolderCategory(folder)
		if !nullableEq(cat, row[1]) || !nullableEq(sub, row[2]) {
			t.Errorf("folder_category(%q) = (%s, %s); want (%s, %s)",
				folder, ptrDebug(cat), ptrDebug(sub),
				valDebug(row[1]), valDebug(row[2]))
		}
	}
}

func nullableEq(got *string, want any) bool {
	if want == nil {
		return got == nil
	}
	w, ok := want.(string)
	return ok && got != nil && *got == w
}

func ptrDebug(p *string) string {
	if p == nil {
		return "None"
	}
	return *p
}

func valDebug(v any) string {
	if v == nil {
		return "None"
	}
	s, _ := v.(string)
	return s
}

