func TestRecordBaselineIsOneTime(t *testing.T) {
	tmp := t.TempDir()
	dbPath := filepath.Join(tmp, "cache.db")
	vault := makeVault(t, tmp)

	n, err := RecordBaselineIfEmpty(VaultGithub, vault, dbPath, nil)
	if err != nil {
		t.Fatalf("record_baseline_if_empty: %v", err)
	}
	if n == nil || *n != 3 { // 3 notes with source (moc skipped)
		t.Fatalf("baseline = %v; want 3", ptrDebugInt(n))
	}
	// second call: baseline exists -> nil, state UNCHANGED even if the
	// vault changed in between (that's the Phase 3 comparison's job)
	writeNote(t, filepath.Join(vault, "AI-Domain", "Agents", "c.md"),
		legacyNote("https://github.com/o/repo9"))
	n2, err := RecordBaselineIfEmpty(VaultGithub, vault, dbPath, nil)
	if err != nil {
		t.Fatalf("record_baseline_if_empty (2nd): %v", err)
	}
	if n2 != nil {
		t.Fatalf("second baseline = %d; want nil (already existed)", *n2)
	}
	db, err := New(dbPath)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if got, err := db.Count(VaultGithub); err != nil || got != 3 {
		t.Fatalf("count = %d (%v); want 3", got, err)
	}
}

func ptrDebugInt(p *int) string {
	if p == nil {
		return "None"
	}
	return fmt.Sprint(*p)
}

