func TestRecordNoteAndUpsert(t *testing.T) {
	tmp := t.TempDir()
	dbPath := filepath.Join(tmp, "cache.db")
	vault := makeVault(t, tmp)
	path := filepath.Join(vault, "AI-Domain", "Agents", "a.md")
	db, err := New(dbPath)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if err := db.RecordNote(VaultGithub, "https://github.com/o/repo1", path,
		strPtr(legacyNote("https://github.com/o/repo1")), strPtr("Agents"), nil,
		nil); err != nil {
		t.Fatal(err)
	}
	if got, err := db.Count(VaultGithub); err != nil || got != 1 {
		t.Fatalf("count = %d (%v); want 1", got, err)
	}
	// re-record with different content -> upsert, not duplicate
	if err := db.RecordNote(VaultGithub, "https://github.com/o/repo1", path,
		strPtr("changed"), strPtr("Agents"), nil, nil); err != nil {
		t.Fatal(err)
	}
	if got, err := db.Count(VaultGithub); err != nil || got != 1 {
		t.Fatalf("count after re-record = %d (%v); want 1", got, err)
	}
	// set_locked roundtrip
	if err := db.SetLocked(VaultGithub, "https://github.com/o/repo1", true); err != nil {
		t.Fatal(err)
	}
	rows, err := db.AllRows(VaultGithub)
	if err != nil {
		t.Fatal(err)
	}
	if !rows["https://github.com/o/repo1"].Locked {
		t.Error("set_locked(true) did not stick")
	}
}

func TestDBPathResolutionAnchorsToAppDir(t *testing.T) {
	// The v0.09.4 split-state bug must not come back: the literal
	// "cache.db" resolves to APP_DIR, never the current working dir. The
	// Go test isolates via GITCURATOR_HOME (the port's test seam for
	// AppDir) instead of touching a real home.
	home := t.TempDir()
	t.Setenv("GITCURATOR_HOME", home)
	db, err := New("cache.db")
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	expected := filepath.Join(home, "cache.db")
	if abs, _ := filepath.Abs(db.Path()); abs != expected {
		t.Errorf("db path = %q; want %q (APP_DIR anchoring)", abs, expected)
	}
	if _, err := os.Stat(expected); err != nil {
		t.Errorf("anchored cache.db not created: %v", err)
	}
}

func TestTwoVaultsAreIndependent(t *testing.T) {
	tmp := t.TempDir()
	dbPath := filepath.Join(tmp, "cache.db")
	vaultA := makeVault(t, tmp)
	vaultB := makeVault(t, filepath.Join(tmp, "other"))
	if _, err := RecordBaselineIfEmpty(VaultGithub, vaultA, dbPath, nil); err != nil {
		t.Fatal(err)
	}
	if _, err := RecordBaselineIfEmpty(VaultWebsites, vaultB, dbPath, nil); err != nil {
		t.Fatal(err)
	}
	db, err := New(dbPath)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	for vault, want := range map[string]int{VaultGithub: 3, VaultWebsites: 3} {
		if got, err := db.Count(vault); err != nil || got != want {
			t.Errorf("count(%s) = %d (%v); want %d", vault, got, err, want)
		}
	}
}

