func TestCorrectionLogRoundtrip(t *testing.T) {
	tmp := t.TempDir()
	db, err := New(filepath.Join(tmp, "cache.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()

	if n, err := db.CorrectionCount(VaultGithub); err != nil || n != 0 {
		t.Fatalf("correction_count = %d (%v); want 0", n, err)
	}
	if err := db.LogCorrection(VaultGithub, "https://x", strPtr("Agents"),
		strPtr("Scraping"), "p/old.md", "p/new.md", ""); err != nil {
		t.Fatal(err)
	}
	if err := db.LogCorrection(VaultGithub, "https://y", strPtr("MCP"),
		strPtr("Agents"), "", "", ""); err != nil {
		t.Fatal(err)
	}
	if n, err := db.CorrectionCount(VaultGithub); err != nil || n != 2 {
		t.Fatalf("correction_count = %d (%v); want 2", n, err)
	}
	if n, err := db.CorrectionCount(VaultWebsites); err != nil || n != 0 {
		t.Fatalf("correction_count(websites) = %d (%v); want 0", n, err)
	}
	recent, err := db.RecentCorrections(VaultGithub, 1)
	if err != nil {
		t.Fatal(err)
	}
	if len(recent) != 1 || recent[0].SourceURL != "https://y" { // newest first
		t.Errorf("recent = %+v; want https://y first", recent)
	}
	history, err := db.CorrectionsFor(VaultGithub, "https://x")
	if err != nil {
		t.Fatal(err)
	}
	if len(history) != 1 {
		t.Fatalf("history = %d rows; want 1", len(history))
	}
	if history[0].FromCategory == nil || *history[0].FromCategory != "Agents" ||
		history[0].ToCategory == nil || *history[0].ToCategory != "Scraping" {
		t.Errorf("history[0] = %+v; want Agents -> Scraping", history[0])
	}
}

func TestDismissRoundtrip(t *testing.T) {
	tmp := t.TempDir()
	db, err := New(filepath.Join(tmp, "cache.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()

	if d, err := db.IsDismissed(VaultGithub, "https://x"); err != nil || d {
		t.Fatalf("is_dismissed = %v (%v); want false", d, err)
	}
	if err := db.Dismiss(VaultGithub, "https://x", "gone.md"); err != nil {
		t.Fatal(err)
	}
	if d, err := db.IsDismissed(VaultGithub, "https://x"); err != nil || !d {
		t.Fatalf("is_dismissed = %v (%v); want true", d, err)
	}
	if d, err := db.IsDismissed(VaultWebsites, "https://x"); err != nil || d {
		t.Fatalf("is_dismissed(websites) = %v (%v); want false", d, err)
	}
	if n, err := db.DismissedCount(VaultGithub); err != nil || n != 1 {
		t.Fatalf("dismissed_count = %d (%v); want 1", n, err)
	}
	// dismiss twice = still one row (INSERT OR REPLACE)
	if err := db.Dismiss(VaultGithub, "https://x", ""); err != nil {
		t.Fatal(err)
	}
	if n, err := db.DismissedCount(VaultGithub); err != nil || n != 1 {
		t.Fatalf("dismissed_count after re-dismiss = %d (%v); want 1", n, err)
	}
	if ok, err := db.ClearDismissed(VaultGithub, "https://x"); err != nil || !ok {
		t.Fatalf("clear_dismissed = %v (%v); want true", ok, err)
	}
	if d, err := db.IsDismissed(VaultGithub, "https://x"); err != nil || d {
		t.Fatalf("is_dismissed after clear = %v (%v); want false", d, err)
	}
	if ok, err := db.ClearDismissed(VaultGithub, "https://x"); err != nil || ok {
		t.Fatalf("clear_dismissed (2nd) = %v (%v); want false", ok, err)
	}
}

