type applyEnv struct {
	tmp   string
	db    string
	dbObj *DB
	vault string
}

func newApplyEnv(t *testing.T) *applyEnv {
	tmp := t.TempDir()
	e := &applyEnv{tmp: tmp, db: filepath.Join(tmp, "cache.db")}
	db, err := New(e.db)
	if err != nil {
		t.Fatal(err)
	}
	e.dbObj = db
	e.vault = ghVault(t, tmp)
	if _, err := RecordBaselineIfEmpty(VaultGithub, e.vault, e.db, nil); err != nil {
		t.Fatal(err)
	}
	return e
}

func (e *applyEnv) close(t *testing.T) {
	t.Helper()
	if err := e.dbObj.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}
}

func (e *applyEnv) classifyAndApply(t *testing.T) (Changes, Summary) {
	t.Helper()
	changes, err := ClassifyChanges(VaultGithub, e.vault, e.db, nil)
	if err != nil {
		t.Fatal(err)
	}
	applied, err := ApplyCorrections(VaultGithub, e.vault, changes, e.dbObj, nil, nil)
	if err != nil {
		t.Fatal(err)
	}
	return changes, applied
}

func TestApplyMovedNoteIsACorrection(t *testing.T) {
	e := newApplyEnv(t)
	defer e.close(t)

	agents, _ := constants.CategoryFolder("Agents")
	scraping, _ := constants.CategoryFolder("Scraping")
	a := filepath.Join(e.vault, agents, "a.md")
	dstDir := filepath.Join(e.vault, scraping)
	if err := os.MkdirAll(dstDir, 0o777); err != nil {
		t.Fatal(err)
	}
	newPath := filepath.Join(dstDir, "a.md")
	if err := os.Rename(a, newPath); err != nil {
		t.Fatal(err)
	}

	changes, applied := e.classifyAndApply(t)
	if len(changes.Moved) != 1 {
		t.Fatalf("moved = %d; want 1", len(changes.Moved))
	}
	if applied.MovedApplied != 1 {
		t.Fatalf("moved_applied = %d; want 1", applied.MovedApplied)
	}

	content, err := os.ReadFile(newPath)
	if err != nil {
		t.Fatal(err)
	}
	s := string(content)
	if !strings.Contains(s, "category: \"Scraping\"") {
		t.Error("category line not updated")
	}
	if !strings.Contains(s, "category_locked: true") {
		t.Error("category_locked line missing")
	}
	if strings.Contains(s, "category: \"Agents\"") {
		t.Error("old category line still there")
	}

	// state row refreshed: new path, new category, locked
	row, err := e.dbObj.RowFor(VaultGithub, "https://github.com/o/repo1")
	if err != nil || row == nil {
		t.Fatalf("row_for: %v (%v)", row, err)
	}
	if row.Path != newPath {
		t.Errorf("row path = %q; want %q", row.Path, newPath)
	}
	if row.Category == nil || *row.Category != "Scraping" {
		t.Errorf("row category = %v; want Scraping", row.Category)
	}
	if !row.Locked {
		t.Error("row not locked")
	}

	// one corrections-log row
	if n, err := e.dbObj.CorrectionCount(VaultGithub); err != nil || n != 1 {
		t.Fatalf("correction_count = %d (%v); want 1", n, err)
	}
	hist, err := e.dbObj.CorrectionsFor(VaultGithub, "https://github.com/o/repo1")
	if err != nil || len(hist) != 1 {
		t.Fatalf("corrections_for: %v (%v)", hist, err)
	}
	if hist[0].ToCategory == nil || *hist[0].ToCategory != "Scraping" {
		t.Errorf("history to_category = %v; want Scraping", hist[0].ToCategory)
	}
}

